using System;using System.Data.SqlClient;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class JobsPage:UserControl{DataGridView g=Ui.Grid();TextBox q=Ui.Text();public JobsPage(){var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=52};q.Width=260;bar.Controls.Add(q);var search=Ui.Button(L.T("search"),false);search.Click+=(s,e)=>LoadData();bar.Controls.Add(search);if(AppSession.Can("Jobs.Manage")){var add=Ui.Button(L.T("add"));add.Click+=Add;bar.Controls.Add(add);}Controls.Add(g);Controls.Add(bar);LoadData();}void LoadData(){g.DataSource=Database.Query("SELECT j.Id,j.Title AS [عنوان / Title],ISNULL(c.Name,'-') AS [شرکت / Company],j.Category AS [دسته / Category],j.City AS [شهر / City],j.EmploymentType AS [نوع / Type],j.Status AS [وضعیت / Status] FROM Jobs j LEFT JOIN Companies c ON c.Id=j.CompanyId WHERE @q='' OR j.Title LIKE @like OR c.Name LIKE @like ORDER BY j.Id DESC",new SqlParameter("@q",q.Text.Trim()),new SqlParameter("@like","%"+q.Text.Trim()+"%"));}void Add(object s,EventArgs e){using(var f=new Form{Text=L.Fa?"فرصت شغلی جدید":"New job",Width=500,Height=520,StartPosition=FormStartPosition.CenterParent}){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(25),WrapContents=false};var title=Ui.Text();title.Width=400;var cat=Ui.Text();cat.Width=400;var city=Ui.Text();city.Width=400;var type=Ui.Text();type.Width=400;foreach(var x in new[]{new Control[]{Ui.Label(L.Fa?"عنوان":"Title"),title},new Control[]{Ui.Label(L.Fa?"دسته‌بندی":"Category"),cat},new Control[]{Ui.Label(L.Fa?"شهر":"City"),city},new Control[]{Ui.Label(L.Fa?"نوع همکاری":"Employment type"),type}}){p.Controls.Add(x[0]);p.Controls.Add(x[1]);}var b=Ui.Button(L.T("save"));b.Click+=(a,z)=>{if(string.IsNullOrWhiteSpace(title.Text))return;Database.Exec("INSERT Jobs(Title,Category,City,EmploymentType,Status) VALUES(@t,@c,@city,@type,'Open')",new SqlParameter("@t",title.Text),new SqlParameter("@c",cat.Text),new SqlParameter("@city",city.Text),new SqlParameter("@type",type.Text));Database.Audit("Create","Job",title.Text);f.Close();LoadData();};p.Controls.Add(b);f.Controls.Add(p);Theme.Apply(f);f.ShowDialog(this);}}}}